"use strict";(self.webpackChunk_servicenow_sdk_docs=self.webpackChunk_servicenow_sdk_docs||[]).push([["549964"],{983959(e){e.exports=JSON.parse('{"tag":{"label":"state transition","permalink":"/sdk/4.11.2/tags/state-transition","allTagsPath":"/sdk/4.11.2/tags","count":2,"items":[{"id":"guides/state-model-guide","title":"State Models","description":"Guide for creating ServiceNow State Models using the Fluent API. A State Model defines the states a record can be in, the valid transitions between them, and the conditions that gate each transition \u2014 for example, blocking a Change from \\"Assess\\" to \\"Authorize\\" until an approval condition is met. A single StateModel() call creates the model record plus all of its state, transition, and condition records.","permalink":"/sdk/4.11.2/guides/state-model-guide"},{"id":"api/statemodel-api","title":"StateModel","description":"Creates a State Model that defines states, transitions, and gating conditions for a table. A single StateModel() call produces the model record plus all of its state, transition, and condition records. The plugin auto-detects the model table from the target table (changerequest \u2192 chgmodel, problem \u2192 prbmodel, problemtask \u2192 prbtaskmodel, any other table \u2192 the base sttrm_model).","permalink":"/sdk/4.11.2/api/statemodel-api"}],"unlisted":false}}')}}]);